/// Whether npm's registry has `package` at `version`, as `npm view` on the
/// host says, remembered once asked: Some(false) where it says it hasn't,
/// None where it can't be asked, as without npm.
fn registry_has(package: &str, version: &str) -> Option<bool> {
    static ASKED: std::sync::LazyLock<std::sync::Mutex<HashMap<String, Option<bool>>>> =
        std::sync::LazyLock::new(Default::default);
    let key = format!("{package}@{version}");
    if let Some(known) = ASKED.lock().unwrap_or_else(|p| p.into_inner()).get(&key) {
        return *known;
    }
    let output = crate::process::command("npm")
        .args(["view", &key, "version"])
        .stdin(Stdio::null())
        .output_logged()
        .ok();
    let has = output.map(|output| {
        let said = String::from_utf8_lossy(&output.stdout);
        output.status.success() && said.lines().any(|line| line.trim().trim_matches('\\'') == version)
    });
    // npm that ran but couldn't reach the registry can't say either way.
    let has = match (has, &output_said_unreachable(&key)) {
        (Some(false), true) => None,
        (has, _) => has,
    };
    ASKED.lock().unwrap_or_else(|p| p.into_inner()).insert(key, has);
    has
}

