/// debug log's last word on it isn't consulted; npm is asked for its ping.
fn output_said_unreachable(_key: &str) -> bool {
    crate::process::command("npm")
        .args(["ping"])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status_logged()
        .is_ok_and(|status| !status.success())
}

