    /// What has to be done before the run can go, once it failed for want
    /// of it.
    pub(crate) fn action(&self) -> Option<RunAction> {
        match self.parts.last() {
            Some(ReplyPart::Action(action)) => Some(*action),
            _ => None,
        }
    }

    /// Adds an error row to the end of the output.
    pub(crate) fn push_error(&mut self, error: String) {
        self.parts.push(ReplyPart::Error(error));
        if let Some(action) = self.pending_action.take() {
            self.parts.push(ReplyPart::Action(action));
        }
        self.refresh();
    }

    /// Adds a notice to the end of the output: passive, never an error, so
    /// it fails nothing and isn't among the run's errors.
    pub(crate) fn push_notice(&mut self, summary: String, details: String) {
        self.parts
            .push(ReplyPart::Notice(Notice { summary, details }));
        self.refresh();
    }

    /// Which part row `ix` shows.
    pub(crate) fn part_of_row(&self, ix: usize) -> Option<usize> {
        match self.rows.get(ix)? {
            RowSource::Part(part) => Some(*part),
            RowSource::Pending => None,
        }
    }

    /// The run's final output, its answer (see [`Layout::of`]): the reply
            .text_sm()
            .text_color(muted)
            .children(notice.details.lines().map(|line| line.to_string()));
        gpui_kit::TestSupportExt::test_support(details)
    });
    // Lets UI tests find the notice; inert in normal builds.
    v_flex()
        .w_full()
        .min_w_0()
        .child(gpui_kit::TestSupportExt::test_support(summary))
        .children(details)
        .into_any_element()
}

/// A message sent to a run while it works: its first line, the whole message
/// as it was typed shown on hover.
/// The button that does `action` for the run of the table `table`, through
/// whatever owns the runs.
pub(crate) fn action_button(
    id: impl Into<ElementId>,
    action: RunAction,
    table: usize,
) -> AnyElement {
    gpui_kit::TestSupportExt::test_support(
        div().id(id).child(
            Button::new("run-action")
                .small()
                .primary()
                .label(action.label())
                .on_click(move |_, window, cx| {
                    if let Some(actions) = cx.try_global::<RunActions>().cloned() {
                        (actions.0)(action, table, window, cx);
                    }
                }),
        ),
    )
    .into_any_element()
}

pub(crate) fn sent_message(id: impl Into<ElementId>, text: &str, cx: &App) -> AnyElement {
    let whole = SharedString::from(text.to_string());
    let line = text
        .lines()
        .find(|line| !line.trim().is_empty())
        .unwrap_or_default()
        .to_string();
    let message = div()
        .id(id)
        .min_w_0()
        .truncate()
        .text_color(cx.theme().foreground)
