                                        cx.emit(LoggedIn);
                                        State::Succeeded
                                    }
                                    Err(Failure::Build(why)) => State::BuildFailed(why),
                                    Err(Failure::Login(why)) => State::Failed(why),
                                };
                            }
                        }
                    }
                    cx.notify();
