                    h_flex().child(
                        Button::new("login-try-again")
                            .small()
                            .label("Try again")
                            .on_click(cx.listener(|this, _, window, cx| this.start(window, cx))),
                    ),
                )
            });
        gpui_kit::TestSupportExt::test_support(view)
    }
}
